+        '/tmp/s',
+      ], faBin: '/ambient/fa');
+      expect(cmd, [
+        '/ambient/fa',
+        'trajectory',
+        'view',
+        's1',
+        '--session-root',
+        '/tmp/s',
+      ]);
+    });
+
+    test('empty args reduce to the binary itself', () {
+      expect(faCliCommand(const [], faBin: '/ambient/fa'), ['/ambient/fa']);
+      expect(faCliCommand(const [], useAmbientFaBin: false), [
+        'dart',
+        'bin/fah.dart',
+      ]);
+    });
+  });
+}
